/** personality×archetypeでジュニアトーナメントセリフを取得 */
function getJuniorTournamentLine(timing, personality, archetype, rng) {
  const timingData = JUNIOR_TOURNAMENT_LINES[timing];
  if (!timingData) return '';
  // 第一分岐はアーキタイプ(2026-08-01 に軸を入れ替え)。探索順は getDialoguePool と同じ
  const lines = getDialoguePool(timingData, { personality, archetype });
  if (!Array.isArray(lines) || lines.length === 0 || lines[0] === '…') return '';
  if (rng) return lines[Engine.rng.int(rng, 0, lines.length - 1)];
  return lines[Math.floor(Math.random() * lines.length)];
}

/** personality×archetypeで4団体勝ち残り対抗戦の試合中セリフを取得 */
function getAutumnWarMatchLine(context, personality, archetype, rng) {
  const contextData = AUTUMN_WAR_MATCH_LINES[context];
  if (!contextData) return '';
  // 第一分岐はアーキタイプ(2026-08-01 に軸を入れ替え)。探索順は getDialoguePool と同じ
  const lines = getDialoguePool(contextData, { personality, archetype });
  if (!Array.isArray(lines) || lines.length === 0 || lines[0] === '…') return '';
  if (rng) return lines[Engine.rng.int(rng, 0, lines.length - 1)];
  return lines[Math.floor(Math.random() * lines.length)];
}

